// 使用链表，逆序打印字符串

#include <stdio.h>
#include <stdlib.h>

struct CharNode {
   char ch;
   struct CharNode *nextch;
};

void PrintRev(struct CharNode *charList) {
   if (charList == NULL)
      return;
   
   if (charList != NULL)
      PrintRev(charList->nextch);
   
   putchar(charList->ch);
}

void GetChars(struct CharNode **charList) {
   char ch;
   struct CharNode *next, *node;
   
   if ((ch = getchar()) != '\n') {
      next = malloc(sizeof(char));
      next->ch = ch;
      next->nextch = NULL;
      *charList = next;
   }
   
   while ((ch = getchar()) != '\n') {
      node = malloc(sizeof(char));
      node->ch = ch;
      node->nextch = NULL;
      
      next->nextch = node;
      next = node;
   }
}

void FreeChars(struct CharNode *charList) {
   struct CharNode *node;
   
   while (charList != NULL) {
      node = charList;
      charList = charList->nextch;
      free(node);
   }
}

int main (void)
{
   struct CharNode *charList = NULL;
   GetChars(&charList);
   PrintRev(charList);
   FreeChars(charList);
   
   printf("\n\nOK");
   getchar();
   return 0;
}

